// 1. Validate Input Payload from FastAPI
const body = $input.first().json.body || $input.first().json;

if (!body.url || !body.job_id || !body.source_id || !body.callback_url) {
  throw new Error('Missing required fields: url, job_id, source_id, callback_url');
}

// Basic security validation: scheme must be http/https
const url = body.url.trim();
if (!url.startsWith('http://') && !url.startsWith('https://')) {
  throw new Error('Invalid URL scheme. Must be http or https.');
}

return [{
  json: {
    job_id: body.job_id,
    source_id: body.source_id,
    url: url,
    callback_url: body.callback_url
  }
}];

// Extract HTML, Remove Boilerplate, Parse Headings & Metadata
const inputData = $input.first().json;
const html = inputData.data || inputData.body || '';
const sourceInfo = $('Validate Input').first().json;

// Lightweight JS HTML sanitizer & extractor for n8n
let cleanText = '';
let title = '';
let description = '';
let canonicalUrl = sourceInfo.url;

// 1. Extract Title
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
if (titleMatch) {
  title = titleMatch[1].trim();
}

// 2. Canonical URL
const canonicalMatch = html.match(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']+)["']/i);
if (canonicalMatch) {
  canonicalUrl = canonicalMatch[1].trim();
}

// 3. Remove Scripts, Styles, Nav, Footer, Comments
let textContent = html
  .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
  .replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, '')
  .replace(/<footer\b[^<]*(?:(?!<\/footer>)<[^<]*)*<\/footer>/gi, '')
  .replace(/<header\b[^<]*(?:(?!<\/header>)<[^<]*)*<\/header>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '');

// 4. Convert headings to Markdown structure
textContent = textContent
  .replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi, '\n\n# $1\n\n')
  .replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, '\n\n## $1\n\n')
  .replace(/<h3[^>]*>([\s\S]*?)<\/h3>/gi, '\n\n### $1\n\n')
  .replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, '\n- $1')
  .replace(/<p[^>]*>([\s\S]*?)<\/p>/gi, '\n$1\n');

// 5. Strip all remaining HTML tags
cleanText = textContent.replace(/<[^>]+>/g, ' ');

// 6. Decode common entities
cleanText = cleanText
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&nbsp;/g, ' ');

// 7. Normalize multiple whitespaces and empty lines
cleanText = cleanText
  .split('\n')
  .map(l => l.trim())
  .filter(l => l.length > 0)
  .join('\n\n');

return [{
  json: {
    job_id: sourceInfo.job_id,
    source_id: sourceInfo.source_id,
    status: cleanText.length > 30 ? 'completed' : 'failed',
    url: sourceInfo.url,
    canonical_url: canonicalUrl,
    title: title || sourceInfo.url,
    content: cleanText,
    language: 'en',
    callback_url: sourceInfo.callback_url,
    error: cleanText.length > 30 ? null : 'Extracted content was empty or below minimum threshold'
  }
}];
